def design(feats):
    X, y = feats.x, feats.y
    n, p = X.shape
    pos = y.astype(bool)
    n1 = pos.sum()
    if n1 == 0 or n1 == n:
        return Design(drivers=(), columns=(), products=(), loadings={})
    d = X[pos].mean(0) - X[~pos].mean(0)
    v = X[pos].var(0, ddof=1) / n1 + X[~pos].var(0, ddof=1) / (n - n1)
    t = d / np.sqrt(v + 1e-12)
    pv = 2 * stats.t.sf(np.abs(t), n - 2)
    order = np.argsort(-np.abs(t))
    sig = [i for i in order if pv[i] < 0.05 / p]
    sel = set()
    pool = sorted(set(sig) | set(order[:15].tolist()))
    try:
        from sklearn.linear_model import LogisticRegressionCV
        lr = LogisticRegressionCV(Cs=10, penalty="l1", solver="liblinear",
                                  cv=5, max_iter=2000, scoring="roc_auc")
        lr.fit(X[:, pool], y)
        sel = set(pool[i] for i in np.flatnonzero(np.abs(lr.coef_[0]) > 1e-8))
    except Exception:
        pass

    def rho(i, j):
        return abs(np.corrcoef(X[:, i], X[:, j])[0, 1])

    keep, members = [], {}
    for i in sorted(sig, key=lambda i: -abs(t[i])):
        # drop Bonferroni hits fully explained by a selected feature
        if sel and i not in sel and any(rho(i, j) >= 0.5 for j in sel):
            continue
        host = next((k for k in keep if rho(i, k) >= 0.6), None)
        if host is None:
            keep.append(i); members[i] = [i]
        else:
            members[host].append(i)

    # interaction scan: unconditional product screen, then conditional LRT
    pm = []
    for i in range(p):
        P = X[:, i, None] * X[:, i + 1:]
        pt = np.abs((P[pos].mean(0) - P[~pos].mean(0)) /
                    np.sqrt(P[pos].var(0, ddof=1) / n1
                            + P[~pos].var(0, ddof=1) / (n - n1) + 1e-12))
        pm += [(pt[k], i, i + 1 + k) for k in np.flatnonzero(pt > 4.5)]
    pm.sort(reverse=True)
    from sklearn.linear_model import LogisticRegression
    from sklearn.metrics import log_loss
    def ll(cols):
        A = np.column_stack(cols)
        m = LogisticRegression(C=1e9, max_iter=300).fit(A, y)
        return -log_loss(y, m.predict_proba(A), normalize=False)
    pairs = []
    for _, i, j in pm[:30]:
        if any(rho(i, a) >= 0.6 and rho(j, b) >= 0.6 for a, b in pairs):
            continue
        base = sorted(set(keep) | {i, j})
        lrt = 2 * (ll([X[:, k] for k in base] + [X[:, i] * X[:, j]])
                   - ll([X[:, k] for k in base]))
        if stats.chi2.sf(max(lrt, 0), 1) < 0.1 / (p * (p - 1) // 2):
            pairs.append((i, j))
    for i, j in pairs:
        for k in (i, j):
            if k not in keep and not any(rho(k, m) >= 0.6 for m in keep):
                keep.append(k); members[k] = [k]
    if not keep:
        return Design(drivers=(), columns=(), products=(), loadings={})
    keep.sort(key=lambda i: -abs(t[i]))
    drv = keep[:MAX_DRIVERS]
    extra = sorted({k for pr in pairs for k in pr} - set(drv),
                   key=lambda i: -abs(t[i]))
    big = max(members.values(), key=len)
    loadings = ({feats.ids[i]: float(np.sign(t[i])) for i in big}
                if len(big) >= 3 else {})
    return Design(drivers=tuple(feats.ids[i] for i in drv),
                  columns=tuple(feats.ids[i] for i in drv + extra),
                  products=tuple((feats.ids[i], feats.ids[j]) for i, j in pairs),
                  loadings=loadings)
